import{_ as e,o,c as r,ag as s}from"./chunks/framework.B3amng90.js";const t="/abu-aigc-guide/screenshots/canvas-list.webp",n="/abu-aigc-guide/screenshots/canvas-nodes.webp",i="/abu-aigc-guide/examples/canvas-reference.webp",l="/abu-aigc-guide/examples/canvas-materials.webp",c="/abu-aigc-guide/examples/canvas-connection.webp",f=JSON.parse('{"title":"用无限画布组合素材","description":"","frontmatter":{},"headers":[],"relativePath":"workflows/canvas.md","filePath":"workflows/canvas.md"}'),p={name:"workflows/canvas.md"};function g(d,a,h,u,m,b){return o(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="用无限画布组合素材" tabindex="-1">用无限画布组合素材 <a class="header-anchor" href="#用无限画布组合素材" aria-label="Permalink to &quot;用无限画布组合素材&quot;">​</a></h1><p>画布适合把创作拆成多个可回看的步骤。文字、图片、视频和音频可以放在不同节点中，再通过连线传递给后续生成。</p><h2 id="新建或打开画布" tabindex="-1">新建或打开画布 <a class="header-anchor" href="#新建或打开画布" aria-label="Permalink to &quot;新建或打开画布&quot;">​</a></h2><p>在侧栏的 <strong>近期画布</strong> 点 <strong>全部</strong>，进入 <strong>我的作品</strong> 页面。选择 <strong>个人画布</strong>，点击 <strong>新建画布</strong>，或打开已有画布继续编辑。</p><p><a href="/abu-aigc-guide/screenshots/canvas-list.webp"><img src="'+t+'" alt="我的作品页的个人画布标签和新建画布卡片" loading="lazy"></a></p><p><em>在「个人画布」里找到新建入口。点击截图可查看大图。</em></p><h2 id="从素材开始生成" tabindex="-1">从素材开始生成 <a class="header-anchor" href="#从素材开始生成" aria-label="Permalink to &quot;从素材开始生成&quot;">​</a></h2><p><a href="/abu-aigc-guide/screenshots/canvas-nodes.webp"><img src="'+n+'" alt="画布左侧加号展开的添加节点菜单，右侧是一个图片节点" loading="lazy"></a></p><p><em>打开画布左侧的加号，可以添加生成节点、文本或已有素材。</em></p><ol><li>点击左侧的 <strong>＋（添加节点）</strong>，添加文本或素材节点，写下提示词，或从资产库选择已保存的图片、视频和音频。</li><li>添加需要的生成节点，并将参考节点连接到它。连线表示哪些内容会作为生成输入。</li><li>选择当前可用的模型，填写提示词并检查生成参数。</li><li>提交任务后，在节点中查看进度和结果。可以调整描述或参数后重新生成，也可以把结果接到下一个节点。</li><li>对满意的结果，可继续用于后续创作或保存到片库。</li></ol><h2 id="跟做案例-·-用未来车站图做视频参考" tabindex="-1">跟做案例 · 用未来车站图做视频参考 <a class="header-anchor" href="#跟做案例-·-用未来车站图做视频参考" aria-label="Permalink to &quot;跟做案例 · 用未来车站图做视频参考&quot;">​</a></h2><p><a href="/abu-aigc-guide/examples/canvas-reference.webp"><img src="'+i+'" alt="将未来车站图片节点连到视频生成节点的示意图" loading="lazy"></a></p><p><em>左侧图片提供建筑外观，右侧视频节点用提示词描述镜头怎么动。示意图使用生产画布中的车站图片。</em></p><h3 id="_1-放入参考图" tabindex="-1">1. 放入参考图 <a class="header-anchor" href="#_1-放入参考图" aria-label="Permalink to &quot;1. 放入参考图&quot;">​</a></h3><p>打开 <strong>资产库 → 生成历史 → 图片</strong>，选择一张正面能看清空间结构的图，例如示例中的玻璃穹顶车站。需要把镜头构思单独保存时，点击左侧 <strong>＋</strong> 添加 <strong>文本</strong> 节点。</p><p><a href="/abu-aigc-guide/examples/canvas-materials.webp"><img src="'+l+'" alt="生产画布中的图片与文本节点" loading="lazy"></a></p><h3 id="_2-引用图片并检查连线" tabindex="-1">2. 引用图片并检查连线 <a class="header-anchor" href="#_2-引用图片并检查连线" aria-label="Permalink to &quot;2. 引用图片并检查连线&quot;">​</a></h3><p>添加 <strong>视频生成</strong> 节点。选中它，点击 <strong>引用画布里的素材</strong>，选择车站图。画布会自动连线。提交前看两处：节点之间是否建立了连线，视频提示词下方的参考素材区是否出现车站缩略图。</p><p><a href="/abu-aigc-guide/examples/canvas-connection.webp"><img src="'+c+'" alt="生产画布的视频节点已引用车站图，底部为全能参考模式" loading="lazy"></a></p><p><em>生产画布截图，视频节点处于生成前的状态。</em></p><h3 id="_3-填提示词、选模型并查看结果" tabindex="-1">3. 填提示词、选模型并查看结果 <a class="header-anchor" href="#_3-填提示词、选模型并查看结果" aria-label="Permalink to &quot;3. 填提示词、选模型并查看结果&quot;">​</a></h3><blockquote><p>镜头沿中央通道缓慢前推，保持车站玻璃穹顶的结构与地面的蓝色反光，人物自然走动，画面稳定。</p></blockquote><p>示例选择 <strong>muse-video</strong> 和 <strong>全能参考</strong>。按模型支持情况选择画幅和时长，再开始生成。生成完成后，在视频节点内播放，确认画面保留了穹顶和中央通道，而且镜头向前移动。需要修改时，先保留同一张参考图，只调提示词里的运镜或节奏，方便比较。</p><h2 id="编辑画布" tabindex="-1">编辑画布 <a class="header-anchor" href="#编辑画布" aria-label="Permalink to &quot;编辑画布&quot;">​</a></h2><p>拖动节点调整布局；拖动节点连接点建立或修改连线。选中节点后，可查看或编辑提示词、素材和生成设置。节点保留生成结果，便于比较迭代版本。图片和视频节点还可使用各自提供的编辑操作。</p><p>画布会自动保存。若同时在多个标签页编辑同一张画布，请留意冲突提示，确认保留正确版本后再继续。</p><h2 id="让结果更可控" tabindex="-1">让结果更可控 <a class="header-anchor" href="#让结果更可控" aria-label="Permalink to &quot;让结果更可控&quot;">​</a></h2><ul><li>一轮只改少数提示词或参数，方便比较差异。</li><li>将常用角色、场景和参考图整理为独立节点，重复使用时不必重新准备。</li><li>生成前确认所选模型支持对应素材类型、画幅和时长。</li><li>使用画布 Agent 修改内容后，检查节点与连线是否符合预期；不合适时使用撤销。</li></ul>',28)])])}const q=e(p,[["render",g]]);export{f as __pageData,q as default};
